var EXTRA=[{"dot": "gray", "j": "Medicina (Kaunas)", "h": "Scelta dell'innesto nel LCA: revisione narrativa fra biomeccanica e biologia", "v": "Revisione narrativa senza metodo di ricerca nell'abstract: mette insieme resistenza dell'innesto, incorporazione biologica e fissazione per una scelta individuale; non ha esiti clinici propri e non indica un innesto vincente.", "pmid": "42796290", "doi": "10.3390/medicina62091683", "temi": ["LCA", "scelta dell'innesto", "revisione narrativa"]}, {"dot": "gray", "j": "Journal of Pediatric Society of North America", "h": "MPFL di revisione nell'adolescente: guida a cause di fallimento e procedure associate", "v": "Revisione narrativa: i fallimenti nascono da fattori anatomici non trattati, errori tecnici o selezione sbagliata; cita trocleoplastica, osteotomie e crescita guidata come procedure associate, senza dati comparativi nell'abstract.", "pmid": "42831186", "doi": "10.1016/j.jposna.2026.100435", "temi": ["MPFL", "instabilità rotulea", "adolescente"]}, {"dot": "gray", "j": "Journal of Pediatric Society of North America", "h": "Primo episodio di lussazione rotulea in età pediatrica: corpo libero e rotula più bassa", "v": "Coorte retrospettiva monocentrica con risonanza: un corpo libero osteocondrale si associa a minore altezza rotulea relativa, riduzione spontanea e età maggiore; nessun confronto con il trattamento successivo.", "pmid": "42824251", "doi": "10.1016/j.jposna.2026.100427", "temi": ["lussazione rotulea", "corpo libero", "pediatrico"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Editoriale: l'artrosi femororotulea non controindica l'osteotomia tibiale alta", "v": "Commento di opinione alla letteratura sull'altezza e sul piano coronale della rotula dopo osteotomia ad apertura mediale; non contiene dati nuovi.", "pmid": "42837200", "doi": "10.1002/arj.70664", "temi": ["osteotomia tibiale alta", "articolazione femororotulea", "editoriale"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Editoriale: tempo di abbandonare le soglie fisse di TT-TG per l'instabilità rotulea", "v": "Hevesi e Krych sostengono soglie aggiustate per altezza e sesso e, a lungo termine, una medicina individualizzata; è l'opposto dell'editoriale di Dejour e Mazy dello stesso numero.", "pmid": "42832252", "doi": "10.1002/arj.70665", "temi": ["instabilità rotulea", "TT-TG", "editoriale"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Editoriale: TT-TG resta la misura preferita, ma l'origine del disallineamento guida", "v": "Dejour e Mazy difendono il TT-TG sul TT-PCL e avvertono che un valore alto non indica da solo l'osteotomia della tuberosità: va individuata la causa; opinione di esperti.", "pmid": "42832267", "doi": "10.1002/arj.70656", "temi": ["instabilità rotulea", "TT-TG", "editoriale"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Editoriale: la fiducia nel ginocchio dopo il LCA non è una cosa sola", "v": "Webster ricorda che la mancanza persistente di fiducia si associa a esiti peggiori ma può nascondere paure di nuova lesione, di funzione o di prestazione; commento senza dati nuovi.", "pmid": "42799329", "doi": "10.1002/arj.70648", "temi": ["LCA", "ritorno allo sport", "psicologia"]}, {"dot": "gray", "j": "Diagnostic and Interventional Imaging", "h": "Editoriale radiologico: lesioni meniscali, estrusione e fratture subcondrali da insufficienza", "v": "Commento di radiologi muscolo-scheletrici sulla cascata meccanica che lega lesioni radiali o radicali, estrusione e frattura da insufficienza subcondrale; abstract non disponibile, contenuto non verificato oltre titolo e parole chiave.", "pmid": "42844144", "doi": "10.1016/j.diii.2026.09.005", "temi": ["estrusione meniscale", "radice meniscale", "imaging"]}, {"dot": "gray", "j": "Journal of Experimental Orthopaedics", "h": "Calcio professionistico: tempo di rientro dopo LCA e nuovo infortunio senza associazione chiara", "v": "Studio basato su dati pubblici dei media su giocatori delle maggiori leghe europee: Cox aggiustato per età e ruolo senza associazione chiara; dati non clinici, limite esplicito del disegno.", "pmid": "42829623", "doi": "10.1002/jeo2.70934", "temi": ["ritorno allo sport", "LCA", "calcio"]}, {"dot": "gray", "j": "Turkish Journal of Trauma and Emergency Surgery", "h": "Rottura del tendine quadricipitale: la fragilità si associa a degenza più lunga e Lysholm peggiore", "v": "Coorte retrospettiva multicentrica con fragilità attribuita a posteriori da due chirurghi; modelli limitati nei predittori, ma il disegno resta osservazionale e non causale.", "pmid": "42841891", "doi": "10.14744/tjtes.2026.36602", "temi": ["apparato estensore", "tendine quadricipitale", "fragilità"]}, {"dot": "gray", "j": "Physiotherapy Canada", "h": "Rientro allo sport dopo protesi totale: revisione di ambito sulle linee guida", "v": "Scoping review: mappa ciò che esiste sulle indicazioni di rientro allo sport dopo TKA; per natura non valuta l'efficacia né sintetizza esiti.", "pmid": "42840866", "doi": "10.3138/ptc-2024-0001", "temi": ["protesi totale", "ritorno allo sport", "revisione di ambito"]}, {"dot": "gray", "j": "Arthroscopy Sports Medicine and Rehabilitation", "h": "Distanza tendine rotuleo-cresta trocleare: un marcatore adesivo riproduce la misura in RM", "v": "Studio retrospettivo di riproducibilità su ginocchia con instabilità rotulea: l'accordo fra la tecnica semplice e quella convenzionale è giudicato ottimo; non valuta se la misura cambi la scelta chirurgica.", "pmid": "42836206", "doi": "10.1002/ars2.70109", "temi": ["instabilità rotulea", "risonanza", "misure"]}, {"dot": "gray", "j": "Current Sports Medicine Reports", "h": "Estrogeni e lisil-ossidasi: una spiegazione biologica del maggior rischio di LCA nelle atlete", "v": "Revisione narrativa che mette insieme dati epidemiologici e meccanicistici sulla reticolazione del collagene; è un'ipotesi biologica, non una dimostrazione, e non propone un intervento.", "pmid": "42842750", "doi": "10.1249/JSR.0000000000001375", "temi": ["LCA", "atlete", "collagene"]}];
var SCOPERTE=[{"t": "Un modello di apprendimento profondo misura da solo il Notch Width Index sulle radiografie", "v": "Un gruppo giapponese (The Knee) ha addestrato un modello di segmentazione su 384 immagini pubbliche e lo ha confrontato con due chirurghi su 33 radiografie antero-posteriori: concordanza ICC 0,525-0,756 contro 0,475-0,562 di una singola lettura manuale, Dice 0,975 ± 0,003, circa 540 volte più veloce; su 500 radiografie esterne la segmentazione peggiora con artrosi e bassa qualità. Vale la deviazione perché porta l'IA su un marcatore di rischio del LCA che i chirurghi misurano male; è un'ipotesi di standardizzazione, non uno strumento clinico.", "pmid": "42833019", "doi": "10.1016/j.knee.2026.104650", "temi": ["intelligenza artificiale", "LCA", "radiografia"]}, {"t": "Un impianto in nylon stampato in 3D per la cartilagine, provato su sei capre", "v": "Studio pilota (Cartilage) su difetti da 10 mm del condilo femorale: microfratture più impianto acellulare stampato in 3D con riempimento al 45% contro sole microfratture, punteggio ICRS II mediano 44 contro 33 (p<0,05), ma con tre ginocchia analizzate per braccio, patologo non in cieco e frammenti di nylon 12 non riassorbibile che restano per sempre con una risposta da corpo estraneo. Vale la deviazione perché mostra un'idea di bioingegneria e il suo punto debole; è preclinico, nessuna indicazione per l'uomo.", "pmid": "42817817", "doi": "10.1177/19476035261487354", "temi": ["cartilagine", "bioingegneria", "stampa 3D"]}, {"t": "Elettroagopuntura con ago grande prima della protesi: un RCT cinese sul dolore acuto", "v": "RCT da Zhongguo Gu Shang su 114 pazienti operati di protesi totale: l'elettroagopuntura prima dell'intervento ha dato HSS a 7 giorni di 76,22 ± 3,51 contro 71,54 ± 6,36 con la stessa tecnica solo dopo (p<0,05) e un dolore più basso nei giorni 4-6; il controllo era un'elettroagopuntura finta. Vale la deviazione perché mostra un filone clinico dell'Asia orientale che raramente si legge; il follow-up si ferma a 7 giorni e gli intervalli di confidenza non sono riportati.", "pmid": "42803050", "doi": "10.12200/j.issn.1003-0034.20250200", "temi": ["agopuntura", "protesi totale", "Cina"]}];
var SOC={"1": {"video": "Per ricostruire il legamento crociato anteriore si può usare un tendine preso dallo stesso paziente. Un gruppo di chirurghi di Milano ha descritto, passo per passo, come prelevare il tendine retto femorale, il più superficiale della parte anteriore della coscia.\n\nSi fa un taglio di circa tre centimetri sopra la rotula, si riconosce un sottile strato di grasso che separa questo tendine dagli strati profondi e lo si preleva con uno strumento tubolare, con il ginocchio leggermente piegato. Gli autori sostengono che così si conservano gli strati profondi del quadricipite.\n\nIl limite: è la descrizione di una tecnica, senza pazienti né risultati. Non dice se questo tendine sia migliore di altri né quanto sia lenta la ripresa della forza dopo il prelievo.\nFonte: PubMed, PMID 42781613.", "linkedin": "Prelievo mini-invasivo del retto femorale per il LCA (D'Ambrosi e coll., Arthrosc Tech, settembre 2026): nota tecnica, livello V, nessun paziente analizzato.\n\nPunti tecnici: incisione longitudinale di circa 3 cm a 3-4 cm dal polo superiore della rotula, piano di dissezione indicato dal sottile strato adiposo fra retto femorale e strati profondi, due incisioni verticali di circa 1 cm ai margini del tendine, dissezione distale-prossimale per circa 8 cm, stripper chiuso da almeno 7 mm con ginocchio a 10°-20° di flessione.\n\nLimiti: nessun esito, nessun intervallo di confidenza; gli esiti citati (deficit estensorio a 6 mesi, recupero comparabile a 12) sono di altri lavori; la lunghezza dell'innesto riportata (28-35 cm) non è coerente con la dissezione descritta e non va usata come dato.\nFonte: PubMed, PMID 42781613.", "instagram": "Un tendine della coscia per ricostruire il crociato.\nUn gruppo di Milano ne descrive il prelievo con un taglio di circa 3 cm.\nÈ una tecnica descritta, non uno studio sui risultati.\nFonte: PubMed, PMID 42781613.", "pazienti": "Per ricostruire il legamento crociato anteriore si usa spesso un tendine preso dallo stesso paziente.\n\nUn gruppo di chirurghi di Milano ha descritto come prelevare il tendine retto femorale, nella parte davanti della coscia, con un taglio di circa tre centimetri.\n\nLo scritto descrive la tecnica ma non riporta risultati su pazienti: la scelta del tendine si discute con il chirurgo, caso per caso.\nFonte: PubMed, PMID 42781613."}};
var SOCV={"1": {"video": {"chir": ["Prelievo mini-invasivo del retto femorale per il LCA: una nota tecnica del Galeazzi di Milano, D'Ambrosi e colleghi, Arthroscopy Techniques, settembre 2026. Livello V, nessun paziente analizzato.", "Incisione longitudinale di circa 3 cm a 3-4 cm dal polo superiore della rotula; il piano di dissezione si riconosce da un sottile strato adiposo fra retto femorale e strati profondi; stripper chiuso da almeno 7 mm con il ginocchio a 10°-20° di flessione.", "Il limite: nessun esito e nessun intervallo di confidenza. Gli esiti citati vengono da altri lavori e la lunghezza dell'innesto riportata, 28-35 cm, non è coerente con la dissezione descritta. È una tecnica descritta, non validata.\nFonte: PubMed, PMID 42781613."], "misto": ["Un gruppo di chirurghi di Milano ha descritto come prelevare il tendine retto femorale per ricostruire il legamento crociato anteriore. È il tendine più superficiale della parte anteriore della coscia.", "Si fa un taglio di circa tre centimetri sopra la rotula, si riconosce un sottile strato di grasso che lo separa dagli strati profondi e lo si preleva con uno strumento tubolare, con il ginocchio leggermente piegato.", "Il limite: è la descrizione di una tecnica, senza pazienti né risultati. Non dice se questo tendine sia migliore di altri né quanto sia lenta la ripresa della forza dopo il prelievo.\nFonte: PubMed, PMID 42781613."], "pazienti": ["Per ricostruire il legamento crociato si usa spesso un tendine preso dal paziente stesso. Dei chirurghi di Milano hanno descritto come prelevarne uno della coscia, il retto femorale.", "Basta un taglio di circa tre centimetri sopra la rotula; gli strati profondi del muscolo vengono lasciati al loro posto.", "Lo scritto non riporta risultati su pazienti: la scelta del tendine si discute con il chirurgo.\nFonte: PubMed, PMID 42781613."]}, "linkedin": {"chir": ["Retto femorale per il LCA: nota tecnica del Galeazzi (D'Ambrosi e coll., Arthrosc Tech, settembre 2026), livello V, nessun paziente analizzato.", "Incisione di circa 3 cm a 3-4 cm dal polo superiore della rotula, due incisioni verticali di circa 1 cm ai margini del tendine, dissezione distale-prossimale per circa 8 cm, stripper chiuso da almeno 7 mm a 10°-20° di flessione.", "Limiti: nessun esito, nessun intervallo di confidenza; gli esiti citati sono di altri lavori e la lunghezza riportata (28-35 cm) non è coerente con la dissezione descritta.\nFonte: PubMed, PMID 42781613."], "misto": ["Prelievo del tendine retto femorale per la ricostruzione del crociato anteriore: una tecnica descritta da un gruppo di Milano (Arthroscopy Techniques, settembre 2026).", "Un accesso di circa 3 cm sopra la rotula, un piano di dissezione riconosciuto da un sottile strato di grasso e uno strumento tubolare che scorre lungo il tendine con il ginocchio leggermente piegato.", "Limite: è la descrizione di una tecnica, senza pazienti operati; non misura la forza dopo il prelievo e non confronta altri innesti.\nFonte: PubMed, PMID 42781613."], "pazienti": ["Un tendine della coscia per ricostruire il legamento crociato: come viene prelevato, secondo un gruppo di Milano.", "Un taglio di circa tre centimetri sopra la rotula; il muscolo sottostante resta al suo posto.", "Lo scritto descrive la tecnica, non i risultati sui pazienti.\nFonte: PubMed, PMID 42781613."]}, "instagram": {"chir": ["Retto femorale per il LCA.", "Nota tecnica, livello V: incisione di circa 3 cm, stripper da almeno 7 mm.", "Nessun esito riportato.\nFonte: PubMed, PMID 42781613."], "misto": ["Un tendine della coscia per il crociato.", "Prelievo con un taglio di circa 3 cm sopra la rotula.", "Tecnica descritta, non uno studio sui risultati.\nFonte: PubMed, PMID 42781613."], "pazienti": ["Un tendine della coscia per il crociato.", "Un taglio di circa tre centimetri, descritto da chirurghi di Milano.", "Nessun risultato sui pazienti: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42781613."]}, "reel": {"chir": ["Retto femorale: prelievo.", "Incisione di 3 cm, stripper da 7 mm.", "Nota tecnica, nessun esito."], "misto": ["Un tendine della coscia.", "Prelevato con un taglio di 3 cm.", "Tecnica, non risultati."], "pazienti": ["Un tendine della coscia.", "Preso con un piccolo taglio.", "Nessun risultato ancora."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #LCA #ChirurgiaDelGinocchio", "instagram": "#ortopedia #ginocchio #legamentocrociato #lca #tendine #chirurgiaartroscopica #chirurgiaortopedica #ortopediaticino #medicinabasatasulleprove #traumatologiadellosport", "kw": "legamento crociato anteriore, tendine retto femorale, prelievo del tendine, ricostruzione del crociato"}};
var NLB={"1": {"prof": ["Prelievo del retto femorale per il LCA: una nota tecnica senza pazienti né esiti", "Un gruppo del Galeazzi di Milano (D'Ambrosi e colleghi, Arthrosc Tech, settembre 2026) descrive il prelievo mini-invasivo del tendine retto femorale, lo strato più superficiale del complesso quadricipitale: incisione longitudinale di circa 3 cm a 3-4 cm dal polo superiore della rotula, due incisioni verticali di circa 1 cm lungo i margini del tendine, dissezione distale-prossimale per circa 8 cm e stripper chiuso da almeno 7 mm con il ginocchio a 10°-20° di flessione. Il piano di dissezione si riconosce da un sottile strato adiposo fra retto femorale e strati profondi.", "Nota critica: è una nota tecnica senza pazienti, misure né intervalli di confidenza; gli esiti che cita (deficit estensorio ancora presente a 6 mesi in uno studio, recupero comparabile a 12 mesi in un altro) vengono da lavori non riletti qui, e la lunghezza dell'innesto riportata nel testo (28-35 cm) non è coerente con la dissezione descritta, quindi non va usata come dato."], "mix": ["Come si preleva il tendine retto femorale per ricostruire il crociato: la tecnica descritta", "Per ricostruire il legamento crociato anteriore si può usare un tendine del paziente stesso. Un gruppo di chirurghi di Milano ha descritto passo per passo il prelievo del retto femorale, il tendine più superficiale della parte anteriore della coscia: un taglio di circa 3 centimetri sopra la rotula, un piano di separazione dagli strati profondi del quadricipite che si riconosce da un sottile strato di grasso, e uno strumento tubolare che scorre lungo il tendine con il ginocchio leggermente piegato.", "Nota sul limite: è la descrizione di una tecnica, non uno studio su pazienti; non misura la forza né il recupero dopo il prelievo e non dice se questo tendine sia migliore di altri."], "paz": ["Il tendine della coscia usato per il crociato: come viene prelevato", "Per ricostruire il legamento crociato anteriore si usa spesso un tendine preso dallo stesso paziente. Un gruppo di chirurghi di Milano ha descritto, passo per passo, come prelevare il tendine retto femorale, che sta nella parte davanti della coscia, attraverso un taglio di circa 3 centimetri sopra la rotula.", "Lo scritto descrive la tecnica ma non riporta risultati su pazienti: non dice se sia più adatta di altre, e la scelta del tendine si discute con il chirurgo, caso per caso."], "kw": "legamento crociato anteriore, tendine retto femorale, prelievo del tendine, ricostruzione del crociato"}, "2": {"prof": ["MPFL con retto femorale libero a doppio fascio: nota tecnica, nessun paziente", "Due autori dell'Ospedale ortopedico di Valdoltra (Slovenia, Arthrosc Tech, ottobre 2026) descrivono la ricostruzione del legamento patello-femorale mediale con innesto libero di retto femorale a doppio fascio, per ottenere una fissazione rotulea anatomica che la tecnica con quadricipite peduncolato, con l'inserzione conservata sul polo superiore della rotula, non permette. Gli autori attribuiscono al retto femorale una resistenza a trazione e un carico al cedimento maggiori dell'hamstring.", "Nota critica: nell'abstract non ci sono pazienti, misure né valori numerici; il confronto con l'hamstring è un'affermazione degli autori e il dettaglio della fissazione non è stato verificato sul testo completo."], "mix": ["Legamento della rotula ricostruito con il tendine retto femorale: una tecnica descritta", "Quando la rotula si lussa può essere necessario ricostruire il legamento che la trattiene all'interno. Due chirurghi sloveni descrivono una tecnica che usa il tendine retto femorale della coscia, diviso in due fasci e fissato alla rotula in modo da imitare la posizione anatomica del legamento originale.", "Nota sul limite: è la descrizione di una tecnica, senza pazienti operati né risultati; la maggiore resistenza rispetto ai tendini della gamba è un'affermazione degli autori, non dimostrata nello scritto."], "paz": ["Rotula instabile: una tecnica per ricostruire il legamento con un tendine della coscia", "Quando la rotula esce spesso dalla sua sede si può ricostruire il legamento che la tiene al suo posto. Due chirurghi hanno descritto una tecnica che usa un tendine preso dalla coscia dello stesso paziente, diviso in due parti e fissato alla rotula.", "Lo scritto descrive la tecnica ma non riporta risultati su pazienti operati: la scelta dell'intervento e del tendine si discute con il chirurgo."], "kw": "instabilità della rotula, legamento patello-femorale mediale, lussazione di rotula, tendine della coscia"}, "3": {"prof": ["Osteotomia tibiale ad apertura mediale: il piano posteriore al collaterale non alza lo slope", "Una coorte retrospettiva di Izmir (J Orthop Surg Hong Kong, 2026) su 62 pazienti confronta tre tecniche di osteotomia ad apertura mediale. Lo slope tibiale posteriore aumenta di 2,12° ± 3,22° con la monoplanare anteriore al collaterale mediale (n=22) e di 3,39° ± 2,76° con la biplanare anteriore (n=18), e diminuisce di 0,88° ± 3,78° con la monoplanare posteriore (n=22); p<0,001 fra gruppi, p=0,011 e p<0,001 per il confronto del gruppo posteriore con gli altri due, anche dopo aggiustamento. La correzione dell'asse è simile nei tre gruppi.", "Nota critica: retrospettivo e non randomizzato, 18-22 pazienti per gruppo, deviazioni standard di 3-4° simili alle differenze; l'abstract non riporta esiti clinici, quindi non si sa se 2-3° di slope in più cambino qualcosa."], "mix": ["Osteotomia della tibia: il punto del taglio cambia l'inclinazione dell'altopiano", "In uno studio su 62 pazienti sono state confrontate tre tecniche di osteotomia della tibia che apre il lato interno per riallineare la gamba. Con i tagli davanti al legamento collaterale mediale l'inclinazione posteriore dell'altopiano tibiale aumenta in media di circa 2-3 gradi; con il taglio dietro lo stesso legamento resta praticamente invariata. Il riallineamento della gamba è stato simile nei tre gruppi.", "Nota sul limite: lo studio guarda indietro nel tempo, i gruppi sono piccoli e non assegnati a caso, e nel riassunto non compaiono dolore e funzione: non si sa se la differenza di inclinazione si senta nel risultato clinico."], "paz": ["Osteotomia della tibia: come il punto del taglio cambia l'inclinazione dell'osso", "Quando il ginocchio è consumato sul lato interno si può correggere l'asse della gamba con un taglio nell'osso della tibia. Uno studio su 62 persone ha confrontato tre modi di eseguire il taglio e ha osservato che l'inclinazione dell'altopiano tibiale cambia di qualche grado a seconda di dove si taglia, mentre il riallineamento è simile.", "Lo studio guarda indietro nel tempo e non dice come stanno dopo i pazienti: la tecnica adatta si decide con il chirurgo, caso per caso."], "kw": "osteotomia tibiale alta, slope tibiale, artrosi del ginocchio, riallineamento della gamba"}, "4": {"prof": ["Protesi totale dopo osteotomia o dopo monocompartimentale: revisioni simili a 11,5 anni", "Una coorte prospettica del Mayo (J Arthroplasty, ottobre 2026) segue 216 TKA di conversione, 134 dopo osteotomia tibiale alta e 82 dopo artroplastica monocompartimentale, per una media di 11,5 anni. Revisioni 4% contro 6% (p=0,91), infezioni 4% contro 2% (p=0,27), reinterventi p=0,34; dopo osteotomia il Knee Society Score funzionale è più alto di 15 punti mediani a 2 anni (p<0,001) e di 10 a 5 anni (p=0,04), con un intervento più lungo (133,5 contro 102,0 minuti) e meno steli (tibiali 15% contro 71%).", "Nota critica: coorti non randomizzate e diverse per indicazione, numeri assoluti di eventi assenti nell'abstract e intervalli non riportati; con circa 5 revisioni per gruppo (stima dalle percentuali) il confronto non esclude un rischio da 0,18 a 2,05 volte."], "mix": ["Protesi dopo un'osteotomia o dopo una protesi parziale: risultati simili a undici anni", "Uno studio americano ha seguito 216 persone che hanno ricevuto una protesi totale di ginocchio dopo un precedente intervento di preservazione, un'osteotomia della tibia (134) o una protesi parziale (82), per una media di 11,5 anni. Reinterventi, infezioni e sostituzioni della protesi sono risultati simili; dopo l'osteotomia la funzione misurata dal Knee Society Score era più alta a 2 e a 5 anni, e l'intervento più lungo di circa mezz'ora.", "Nota sul limite: i due gruppi non sono stati formati a caso e possono differire per età e gravità; il numero di eventi è piccolo, per cui «nessuna differenza» non significa che i rischi siano uguali."], "paz": ["Protesi di ginocchio dopo un'osteotomia o una protesi parziale: come vanno a lungo termine", "Se in passato si è fatta un'osteotomia o una protesi parziale, può arrivare il momento di una protesi totale. Uno studio su 216 persone seguite in media undici anni non ha trovato differenze importanti nella necessità di rifare la protesi o nelle infezioni fra chi veniva dall'una o dall'altra strada.", "Lo studio non assegna le persone a caso ai due gruppi: ogni caso va valutato con il chirurgo."], "kw": "protesi totale di ginocchio, osteotomia tibiale alta, protesi monocompartimentale, conversione protesica"}, "5": {"prof": ["LCA con hamstring in adolescenti: a 4 mesi nessun deficit dell'arto operato, LSI in calo", "Una coorte retrospettiva monocentrica di Montréal (J Exp Orthop, ottobre 2026) su 93 adolescenti (15,6 ± 1,3 anni) con LCA e autoinnesto di hamstring misura la forza isocinetica a 180°/s, da seduti. A 4 mesi l'arto operato non differisce dal preoperatorio né in flessione (p=0,672) né in estensione (p=0,316), mentre l'arto sano guadagna in entrambe (p<0,001); l'LSI cala (p<0,001) di 12% in estensione e di 7% in flessione, senza differenze fra i sessi.", "Nota critica: nessun gruppo con un altro innesto, un solo test e un solo tempo (4 mesi); «nessuna differenza» senza intervalli non prova l'assenza di deficit, e la simmetria va letta con i valori assoluti dei due arti."], "mix": ["Crociato con tendine della gamba negli adolescenti: a 4 mesi la forza non è calata", "In 93 adolescenti operati di legamento crociato con un tendine della gamba, a 4 mesi la forza di flessione e di estensione del ginocchio operato non era diversa da prima dell'intervento. L'indice di simmetria fra le due gambe è sceso, ma soprattutto perché la gamba sana aveva guadagnato forza, più in estensione (12%) che in flessione (7%).", "Nota sul limite: lo studio guarda indietro nel tempo, non confronta altri tendini e si ferma a 4 mesi con un solo test: dice poco su quando sia sicuro tornare allo sport."], "paz": ["Crociato operato in età adolescenziale: la forza dopo 4 mesi", "In uno studio su 93 ragazzi e ragazze operati al legamento crociato con un tendine della gamba, dopo 4 mesi la forza del ginocchio operato non era inferiore a quella di prima dell'intervento. Il confronto con la gamba sana risultava più sfavorevole soprattutto perché la gamba sana era diventata più forte.", "Lo studio guarda solo i primi 4 mesi e un solo tipo di test: il rientro allo sport si decide con il chirurgo e il fisioterapista."], "kw": "legamento crociato anteriore, adolescenti, forza muscolare, riabilitazione dopo crociato"}, "6": {"prof": ["Contraccettivi orali e LCA: nessuna associazione chiara in 10 studi, certezza molto bassa", "Una revisione sistematica con meta-analisi (J Exp Orthop, ottobre 2026) su 10 studi osservazionali, 7 meta-analizzati, non trova un'associazione chiara fra contraccettivi orali e ricostruzione o lesione operata del LCA: OR 0,89 (IC 95% 0,77-1,02; intervallo di predizione 0,66-1,19) nell'analisi primaria su 4 studi, HR 0,95 (0,89-1,01) nella coorte con comparatore attivo.", "Nota critica: eterogeneità elevata (84% nell'analisi primaria), leave-one-out instabile, definizioni di esposizione diverse e certezza GRADE molto bassa; gli autori escludono una lettura causale e non raccomandano i contraccettivi per la prevenzione."], "mix": ["Pillola anticoncezionale e rottura del crociato: nessun legame chiaro negli studi", "Una revisione di 10 studi ha cercato un legame fra la pillola anticoncezionale e la rottura del legamento crociato anteriore nelle donne. Nell'analisi principale, su 4 studi, il rischio risulta di poco inferiore ma statisticamente compatibile con nessuna differenza (0,89, con un intervallo da 0,77 a 1,02).", "Nota sul limite: gli studi sono osservazionali, molto diversi fra loro e con una certezza giudicata molto bassa: non si può concludere che la pillola protegga né che danneggi, e non è un motivo per iniziarla o sospenderla."], "paz": ["Pillola anticoncezionale e legamento crociato: cosa dicono gli studi", "Alcune donne si chiedono se la pillola anticoncezionale influenzi il rischio di rottura del legamento crociato. Una revisione di 10 studi non ha trovato un legame chiaro, né in un senso né nell'altro.", "Le prove sono poche e di bassa qualità: la pillola non va iniziata né sospesa per questo motivo, e la scelta si discute con il medico curante."], "kw": "legamento crociato anteriore, pillola anticoncezionale, rischio nelle donne, lesioni sportive"}, "7": {"prof": ["UKA mediale con varo ≥10°: esiti a 10 anni simili se il JLCA postoperatorio è 0°-5°", "Una coorte appaiata di Heidelberg (KSSTA, ottobre 2026) su 132 coppie di UKA mediali mobile-bearing, seguite 10,1 ± 3,3 anni, non trova differenza fra varismo preoperatorio ≥10° e <10°: OKS 40,6 ± 8,0 contro 38,8 ± 5,7, sopravvivenza senza revisione a 10 anni 92,3% contro 90,2% (p=0,618). Nel gruppo ≥10° un JLCA fuori da 0°-5° di varo dà OKS 35,6 ± 11,0 contro 42,4 ± 6,2 (p=0,022) e un inserto ≥7 mm OKS 32,1 ± 12,1 contro 41,2 ± 5,9 (p=0,004).", "Nota critica: retrospettivo e monocentrico; le soglie di JLCA e di inserto sono ricavate dagli stessi dati con sottogruppi piccoli, e con circa 10 e 13 revisioni (stima dalle percentuali) l'intervallo del rischio relativo va da 0,35 a 1,69."], "mix": ["Protesi parziale in ginocchi molto storti: risultati simili a dieci anni se l'asse è corretto", "In 132 coppie di pazienti operati di protesi parziale del lato interno, chi aveva una deformità in varo di almeno 10° prima dell'intervento ha avuto, a circa dieci anni, risultati e durata della protesi simili a chi aveva una deformità minore (protesi ancora in sede in circa il 92% contro il 90%). Nel gruppo con deformità maggiore i risultati erano peggiori quando l'angolo della linea articolare dopo l'intervento era fuori da un intervallo preciso o l'inserto era troppo spesso.", "Nota sul limite: studio retrospettivo di un solo centro; le soglie sono state calcolate sugli stessi pazienti e vanno confermate in altri gruppi."], "paz": ["Protesi parziale con gamba a «O» marcata: come vanno i pazienti dopo dieci anni", "Uno studio su 132 coppie di pazienti ha confrontato chi aveva una gamba a «O» molto accentuata con chi l'aveva meno prima di una protesi parziale. Dopo circa dieci anni funzione e durata della protesi erano simili nei due gruppi, a patto che l'angolo dell'articolazione dopo l'intervento fosse corretto.", "Lo studio guarda indietro nel tempo e proviene da un solo centro: ogni caso va valutato con il chirurgo."], "kw": "protesi monocompartimentale, gamba a O, artrosi del lato interno, durata della protesi"}, "8": {"prof": ["Lesione del menisco laterale e UKA mediale: nessuna differenza di funzione in 8 coorti", "Una meta-analisi di 8 coorti retrospettive (1709 pazienti; Front Surg, settembre 2026) non trova differenze postoperatorie fra UKA mediale con e senza anomalie del menisco laterale: funzione SMD −0,06 (IC 95% da −0,26 a 0,14), mobilità MD 0,17° (da −1,58° a 1,92°), dolore laterale RR 1,10 (da 0,32 a 3,81).", "Nota critica: solo coorti retrospettive con definizioni diverse di lesione e pochi eventi di revisione; l'intervallo del dolore laterale è molto largo e gli autori escludono lesioni sintomatiche, instabili, traumatiche, radici e perdita avanzata di cartilagine laterale."], "mix": ["Protesi parziale interna con menisco esterno consumato: risultati simili a medio termine", "Otto studi su 1709 pazienti non mostrano differenze di funzione, mobilità e dolore sul lato esterno fra chi aveva e chi non aveva anomalie del menisco laterale prima di una protesi parziale del lato interno. Gli autori concludono che un'anomalia lieve e senza sintomi non è da sola un motivo per escludere questo intervento.", "Nota sul limite: gli studi sono retrospettivi e gli eventi poco numerosi; il risultato non vale per lesioni con sintomi, instabili, da trauma o alla radice del menisco."], "paz": ["Menisco esterno danneggiato e protesi parziale: cosa dicono gli studi", "Prima di una protesi parziale del lato interno del ginocchio, a volte il menisco del lato esterno non è perfetto. Otto studi su 1709 pazienti non hanno trovato risultati peggiori in chi aveva piccole alterazioni senza sintomi.", "Gli studi guardano indietro nel tempo e non valgono per lesioni importanti del menisco: la valutazione è individuale."], "kw": "protesi parziale di ginocchio, menisco laterale, artrosi del lato interno, protesi monocompartimentale"}, "9": {"prof": ["Bi-UKA o TKA nell'artrosi bicompartimentale: nessuna differenza di FJS a 24 mesi", "Un RCT esplorativo di Teheran (J Arthroplasty, ottobre 2026) confronta Bi-UKA e TKA con conservazione del crociato in 56 pazienti analizzati (26 e 30) con artrosi femoro-tibiale bicompartimentale e crociati integri. Forgotten Joint Score a 24 mesi: differenza −4,91 punti (IC 95% da −17,92 a 8,09; p=0,453); nessuna differenza di WOMAC, KSS, OKS e VAS; nessuna complicanza maggiore, reintervento o revisione.", "Nota critica: studio esplorativo con analisi per protocollo su casi completi; l'intervallo non esclude differenze di molti punti in entrambe le direzioni e 24 mesi non dicono nulla su usura e revisioni."], "mix": ["Due protesi parziali o una totale: risultati simili dopo due anni in un piccolo studio", "In uno studio randomizzato su 56 pazienti con artrosi di due compartimenti, due protesi parziali nello stesso ginocchio e una protesi totale hanno dato, a 24 mesi, una sensazione di «ginocchio dimenticato» simile e le stesse valutazioni di dolore e funzione. Nessun paziente ha avuto complicanze maggiori o è stato rioperato.", "Nota sul limite: pochi pazienti, un solo centro e solo due anni di controllo: lo studio non dice se le due protesi parziali durino quanto la protesi totale."], "paz": ["Due protesi parziali o una protesi totale: cosa dice un piccolo studio", "Quando l'artrosi interessa due parti del ginocchio si può usare una protesi totale oppure due protesi parziali. In uno studio su 56 pazienti, dopo due anni, le sensazioni riferite e la funzione erano simili con le due scelte.", "Lo studio è piccolo e breve: la durata delle protesi nel tempo non è nota e la scelta si discute con il chirurgo."], "kw": "protesi di ginocchio, artrosi bicompartimentale, protesi parziale, protesi totale"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Arthrosc Tech",h:"Retto femorale: prelievo con 3 cm di incisione, secondo D'Ambrosi",v:"Nota tecnica del Galeazzi (Milano) sul prelievo del retto femorale, strato superficiale del tendine quadricipitale: incisione di circa 3 cm, 3-4 cm sopra il polo superiore della rotula, stripper chiuso da almeno 7 mm con il ginocchio a 10°-20°. Nessun paziente, nessun esito. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"D'Ambrosi, Mei, Muscarella, Di Pace, Picori, Sconfienza, Ursino",date:"set 2026",meta:"nota tecnica, nessun paziente analizzato · [V]",pmid:'42781613',doi:'10.1002/atn2.70279',journal:"Arthroscopy techniques",authors:"D'Ambrosi R, Mei A, Muscarella R, Di Pace A, Picori E, Sconfienza LM, Ursino N",design:"Nota tecnica (Arthroscopy Techniques) con video e figure su modello anatomico e risonanza: descrive passo per passo il prelievo mini-invasivo del tendine retto femorale per la ricostruzione del LCA. Nessun gruppo, nessuna misura di esito. Livello V per tipologia (gli autori non dichiarano un livello). Testo completo aperto su PMC: tecnica, tabelle e limiti letti nel testo, non solo nell'abstract.",pop:"Nessun paziente analizzato: non riportato. Un caso illustrativo con consenso scritto alla pubblicazione di foto e video intraoperatori.",results:"Nessun dato di esito. Parametri tecnici descritti: paziente supino con ginocchio a 90° su doppio appoggio; incisione longitudinale di circa 3 cm a 3-4 cm dal polo superiore della rotula, centrata fra il punto medio e il bordo laterale della rotula; piano di dissezione riconosciuto da un sottile strato adiposo fra retto femorale e strati profondi; due incisioni verticali di circa 1 cm e profonde pochi millimetri ai margini del tendine; dissezione distale-prossimale per circa 8 cm; stripper chiuso di almeno 7 mm con il ginocchio a 10°-20° di flessione. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: il retto femorale si può prelevare con un accesso mini-invasivo riproducibile, preservando gli strati profondi del quadricipite e la continuità dell'apparato estensore; servono studi randomizzati con follow-up lungo.",limits:"Nessun paziente e nessun esito: la nota non dimostra che il prelievo sia più sicuro di altri, solo come lo si esegue · gli esiti citati dagli autori (deficit estensorio ancora presente a 6 mesi in uno studio, recupero comparabile a 12 mesi in un altro) vengono da lavori che qui non sono stati riletti · la lunghezza dell'innesto riportata nel testo (28-35 cm) non è coerente con la dissezione di circa 8 cm descritta e non è sostenuta da misure in questa nota: non la uso come dato.",perte:"È il tuo innesto di default e l'autore è il tuo riferimento: la nota descrive il prelievo, non lo valida, e gli stessi autori elencano come svantaggi la curva di apprendimento e la debolezza estensoria transitoria. Il deficit a 6 mesi che citano è coerente con quello già in tensione sul criterio di rientro, ma qui non c'è un dato nuovo e nessuna tensione si muove."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Arthrosc Tech",h:"MPFL a doppio fascio con retto femorale libero: nota tecnica",v:"Nota tecnica di due autori sloveni: ricostruzione del MPFL con retto femorale libero a doppio fascio, per una fissazione rotulea anatomica che il MPFL con quadricipite peduncolato non permette. Nessun paziente, nessun esito. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Novak, Povh",date:"ott 2026",meta:"nota tecnica, nessun paziente analizzato · [V]",pmid:'42831219',doi:'10.1002/atn2.70263',journal:"Arthroscopy techniques",authors:"Novak S, Povh M",design:"Nota tecnica (Arthroscopy Techniques) dell'Ospedale ortopedico di Valdoltra (Ankaran, Slovenia): ricostruzione del legamento patello-femorale mediale con innesto libero di retto femorale a doppio fascio. Nessun gruppo di confronto. Livello V per tipologia. Testo completo non aperto: contenuto dall'abstract.",pop:"Nessun paziente analizzato nell'abstract: non riportato.",results:"Nessun dato di esito. Gli autori affermano che il retto femorale ha resistenza a trazione e carico al cedimento maggiori dell'hamstring e che il metodo consente una fissazione rotulea anatomica, a differenza della tecnica classica con quadricipite che conserva l'inserzione sul polo superiore della rotula; nell'abstract nessun valore numerico. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: il doppio fascio con retto femorale libero unisce le proprietà biomeccaniche del tendine alla precisione anatomica di un innesto libero.",limits:"Nessun paziente, nessun esito clinico, nessuna misura di stabilità rotulea · il confronto biomeccanico con l'hamstring è un'affermazione degli autori, senza numeri nell'abstract · testo completo non letto: fissazione, tunnel e ancore non verificati.",perte:"Fai l'MPFL con ancore FiberTak in tecnica onlay: qui l'innesto è un retto femorale libero a doppio fascio e il dettaglio della fissazione non è nell'abstract, quindi non è il tuo costrutto. Interessa perché il retto femorale è il tuo innesto per il crociato; non muove nessuna tensione."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"J Orthop Surg (Hong Kong)",h:"Osteotomia mediale: il piano posteriore al collaterale non alza lo slope",v:"Coorte retrospettiva di 62 pazienti, tre tecniche di osteotomia ad apertura mediale: lo slope tibiale posteriore sale di 2,12° ± 3,22° e 3,39° ± 2,76° con i due piani anteriori al collaterale mediale e scende di 0,88° ± 3,78° con quello posteriore (p<0,001). Esiti clinici non riportati nell'abstract.",ax:"Eyceyurt, Suer, Uzakgider, Celebi, Saruhan, Tahta, Kayali",date:"ott 2026",meta:"coorte retrospettiva comparativa, 62 pazienti in 3 gruppi · [III per disegno]",pmid:'42842733',doi:'10.1177/10225536261496570',journal:"Journal of orthopaedic surgery (Hong Kong)",authors:"Eyceyurt RS, Suer O, Uzakgider M, Celebi F, Saruhan SC, Tahta M, Kayali C",design:"Studio retrospettivo comparativo, Izmir (Turchia): osteotomia tibiale ad apertura mediale (MOWHTO) per gonartrosi mediale con varismo in tre tecniche: monoplanare anteriore al collaterale mediale (A), biplanare anteriore (B), monoplanare posteriore al collaterale mediale (C). Esiti radiografici (asse meccanico, slope tibiale posteriore, indici di altezza rotulea, Kellgren-Lawrence) e clinici (Lysholm, VAS). Livello non dichiarato; III per disegno. Testo completo non disponibile in PMC: numeri dall'abstract.",pop:"62 pazienti: A 22, B 18, C 22. Età, sesso, follow-up e correzione ottenuta: non riportati nell'abstract.",results:"Slope tibiale posteriore: A +2,12° ± 3,22°, B +3,39° ± 2,76°, C −0,88° ± 3,78° (differenza fra gruppi p<0,001; C contro A p=0,011; C contro B p<0,001), con effetto che resta significativo dopo aggiustamento per età, sesso, follow-up, slope preoperatorio, entità della correzione e grado di Kellgren-Lawrence. Correzione dell'asse meccanico significativa in tutti i gruppi (p<0,001). Lysholm, VAS e indici di altezza rotulea: valori non riportati nell'abstract. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: le osteotomie monoplanare e biplanare anteriori al collaterale mediale si associano a un aumento maggiore dello slope rispetto alla monoplanare posteriore, a parità di correzione coronale.",limits:"Retrospettivo e non randomizzato, 18-22 pazienti per gruppo: la scelta della tecnica può dipendere da periodo, operatore o anatomia, non riportati · nessun esito clinico nell'abstract, quindi non si sa se 2-3° di slope in più cambino qualcosa per il paziente · slope misurato su radiografie, deviazioni standard di 3-4° comparabili con le differenze fra i gruppi.",perte:"Fai osteotomie e correzioni di slope: qui lo slope è un effetto collaterale dell'apertura mediale e si associa al piano di osteotomia rispetto al collaterale mediale. Vale come promemoria di pianificazione, non come prova che il piano posteriore sia clinicamente migliore; non muove nessuna tensione."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"J Arthroplasty",h:"TKA dopo osteotomia o UKA: stessa sopravvivenza a 11,5 anni",v:"Coorte prospettica del Mayo di 216 TKA di conversione (134 dopo osteotomia, 82 dopo UKA), follow-up medio 11,5 anni: revisioni 4% contro 6% (p=0,91), infezioni 4% contro 2% (p=0,27); KSS funzionale più alto dopo osteotomia a 2 anni (differenza mediana 15 punti, p<0,001) e a 5 (10 punti, p=0,04).",ax:"Bax, Ahmad, Clark, van Egmond, Taunton, Pagnano, Sierra, Hevesi, Saris",date:"ott 2026",meta:"coorte prospettica comparativa monocentrica, 216 pazienti · [III per disegno]",pmid:'42843680',doi:'10.1016/j.arth.2026.09.046',journal:"The Journal of arthroplasty",authors:"Bax EA, Ahmad RA, Clark SC, van Egmond N, Taunton MJ, Pagnano MW, Sierra RJ, Hevesi M, Saris DBF",design:"Coorte prospettica monocentrica (Mayo Clinic, Rochester) di pazienti operati di TKA dopo osteotomia tibiale alta o dopo artroplastica monocompartimentale ipsilaterale fra il 2000 e il 2023. Sopravvivenza senza revisione con Kaplan-Meier, Cox per infezioni e reinterventi, Knee Society Score (differenza minima rilevante 6 punti) e mobilità. Livello non dichiarato; III per disegno. Testo completo non disponibile in PMC: numeri dall'abstract.",pop:"216 pazienti: 134 TKA dopo osteotomia, 82 dopo UKA; follow-up medio 11,5 anni dalla TKA (range da 0 a 24,0).",results:"Revisione 4% contro 6% (p=0,91), infezione 4% contro 2% (p=0,27), reinterventi per qualsiasi causa p=0,34 (osteotomia contro UKA). Componenti con stelo: tibiali 71% contro 15% e femorali 21% contro 5% (p<0,001, più frequenti dopo UKA); durata dell'intervento 133,5 contro 102,0 minuti (più lunga dopo osteotomia, p<0,001). KSS funzionale più alto dopo osteotomia: differenza mediana 15 punti a 2 anni (p<0,001) e 10 a 5 anni (p=0,04). Numeri assoluti degli eventi e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: nessuna differenza significativa di revisione, infezione e reinterventi dopo osteotomia o UKA; l'osteotomia resta una opzione di preservazione articolare in pazienti selezionati.",limits:"Non randomizzato: le due coorti differiscono per indicazione, età e livello di danno, non riportati nell'abstract · eventi pochi e conteggi assoluti assenti: «nessuna differenza» non prova equivalenza · KSS funzionale senza intervallo di confidenza e senza aggiustamento dichiarato; follow-up da 0 a 24 anni, quindi molto disomogeneo.",perte:"Fai osteotomie: il dato che ti serve è che la conversione a TKA dopo osteotomia non risulta penalizzata in sopravvivenza né in infezioni, al prezzo di un intervento più lungo di circa 30 minuti. Nessuna tecnica tua viene contraddetta; non muove nessuna tensione."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"J Exp Orthop",h:"LCA hamstring negli adolescenti: forza a 4 mesi invariata, LSI in calo",v:"Coorte retrospettiva di 93 adolescenti (15,6 ± 1,3 anni) con LCA e hamstring: a 4 mesi nessun deficit significativo dell'arto operato rispetto al preoperatorio in flessione (p=0,672) né in estensione (p=0,316); la simmetria (LSI) cala del 12% in estensione e del 7% in flessione (p<0,001) perché l'arto sano guadagna forza.",ax:"Bazebi, Mazy, David, Wang, Delisle, Grimard, Nault",date:"ott 2026",meta:"coorte retrospettiva monocentrica, 93 pazienti ≤18 anni · [III]",pmid:'42841077',doi:'10.1002/jeo2.70926',journal:"Journal of experimental orthopaedics",authors:"Bazebi M, Mazy D, David Z, Wang S, Delisle A, Grimard G, Nault ML",design:"Studio retrospettivo monocentrico (CHU Sainte-Justine, Montréal) su pazienti ≤18 anni con LCA primario con autoinnesto di hamstring omolaterale fra gennaio 2022 e gennaio 2025: coppia di picco isocinetico in flessione ed estensione a 180°/s, seduti, prima dell'intervento e a 4 mesi; limb symmetry index (LSI). Livello III secondo gli autori (caso-controllo retrospettivo), ma il confronto è fra tempi sullo stesso paziente e con l'arto sano. Testo completo su PMC non aperto: numeri dall'abstract.",pop:"93 pazienti, età media 15,6 ± 1,3 anni; distribuzione per sesso e lesioni associate: non riportate nell'abstract.",results:"Arto operato, 4 mesi contro preoperatorio: flessione p=0,672, estensione p=0,316 (nessuna differenza significativa). Arto sano: aumento significativo in flessione ed estensione (p<0,001). LSI in calo (p<0,001): −12% in estensione contro −7% in flessione; nessuna differenza fra femmine e maschi. Valori medi delle coppie, differenze con intervalli di confidenza: non riportati nell'abstract.",concl:"Gli autori: l'hamstring omolaterale non si associa a deficit di flessione o estensione a 4 mesi; l'asimmetria è dovuta soprattutto al guadagno dell'arto sano; il rinforzo del quadricipite non va trascurato anche con hamstring.",limits:"Nessun gruppo con un altro innesto: non dice che l'hamstring sia meglio o peggio di altri · un solo tempo (4 mesi), un solo test (180°/s, seduto): niente a 6-12 mesi, niente salto o rientro allo sport · «nessuna differenza» con p=0,672 e p=0,316 senza intervalli non prova l'assenza di deficit.",perte:"Non è il tuo innesto (hamstring, non retto femorale o quadricipite) e a 4 mesi non è il momento del rientro. Il dato che serve alla tensione sul criterio di rientro è metodologico: la LSI può scendere perché migliora l'arto sano, non perché peggiora l'operato, quindi una soglia di simmetria va letta insieme ai valori assoluti dei due arti."},{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"J Exp Orthop",h:"Contraccettivi orali e LCA: nessuna associazione chiara, certezza molto bassa",v:"Revisione sistematica di 10 studi osservazionali (7 meta-analizzati): OR 0,89 (IC 95% 0,77-1,02; intervallo di predizione 0,66-1,19) per ricostruzione o lesione operata; coorte con comparatore attivo HR 0,95 (0,89-1,01). Certezza GRADE molto bassa, eterogeneità elevata.",ax:"Kobayashi, Silva, de Azevedo, de Abreu, Malpaga, de Oliveira, Jorge",date:"ott 2026",meta:"revisione sistematica con meta-analisi di studi osservazionali, 10 studi · [IV]",pmid:'42840850',doi:'10.1002/jeo2.70940',journal:"Journal of experimental orthopaedics",authors:"Kobayashi EN, Silva NZ, de Azevedo LAC, de Abreu MEC, Malpaga JMD, de Oliveira DE, Jorge PB",design:"Revisione sistematica con meta-analisi di studi osservazionali comparativi (PubMed, Scopus, Embase, LILACS fino al 31 luglio 2026): OR aggiustati o appaiati per ricostruzione o lesione operata del LCA, modelli a effetti casuali con intervalli di Hartung-Knapp. Rischio di bias con ROBINS-E, certezza con GRADE. Livello IV secondo gli autori. Testo completo su PMC non aperto: numeri dall'abstract.",pop:"10 studi inclusi, 7 meta-analizzati; analisi primaria su 4 studi. Numero di donne: non riportato nell'abstract.",results:"Analisi primaria (4 studi): OR 0,89 (IC 95% 0,77-1,02; intervallo di predizione 0,66-1,19; eterogeneità 84%). Coorte con comparatore attivo: HR 0,95 (IC 95% 0,89-1,01). Aggiungendo una stima grezza da database: OR 0,85 (IC 95% 0,74-0,98; intervallo di predizione 0,61-1,19). Due studi grezzi su atlete con IC che comprendono 1. Analisi leave-one-out instabili. Certezza molto bassa.",concl:"Gli autori: nessuna associazione chiara fra contraccettivi orali e ricostruzione del LCA; eterogeneità, confondimento residuo e certezza molto bassa impediscono una lettura causale; i dati non sostengono l'uso dei contraccettivi per prevenire la lesione.",limits:"Solo quattro studi nell'analisi primaria, eterogeneità elevata e leave-one-out instabile · esposizione e esito definiti in modo diverso fra gli studi · confondimento residuo non eliminabile in studi osservazionali.",perte:"Non tocca la tua tecnica: è prevenzione e consulenza, utile se una paziente chiede se la pillola c'entri con il crociato. Risposta onesta: non c'è un segnale chiaro, con certezza molto bassa."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Knee Surg Sports Traumatol Arthrosc",h:"UKA con varo ≥10°: esiti a 10 anni uguali se il JLCA è 0°-5°",v:"Coorte appaiata di 132 coppie (264 ginocchia), UKA mobile-bearing a 10,1 ± 3,3 anni: OKS 40,6 ± 8,0 contro 38,8 ± 5,7, sopravvivenza senza revisione 92,3% contro 90,2% (p=0,618); JLCA fuori da 0°-5° di varo: OKS 35,6 ± 11,0 contro 42,4 ± 6,2 (p=0,022).",ax:"Weishorn, Bonnmann, Trefzer, Hariri, Mick, Lunz, Walker, Koch",date:"ott 2026",meta:"coorte retrospettiva appaiata, 132 coppie · [III]",pmid:'42841791',doi:'10.1002/ksa.70636',journal:"Knee surgery, sports traumatology, arthroscopy : official journal of the ESSKA",authors:"Weishorn J, Bonnmann S, Trefzer R, Hariri M, Mick P, Lunz A, Walker T, Koch KA",design:"Analisi retrospettiva appaiata 1:1 (Heidelberg) di UKA mediale mobile-bearing con varismo preoperatorio ≥10° contro <10°, su radiografie in carico a lunghezza intera (HKA, JLCA, deformità extra-articolare, mMPTA, mLDFA, obliquità); regressione e curve ROC per soglie di PASS. Livello III dichiarato. Testo completo su PMC non disponibile: numeri dall'abstract.",pop:"132 coppie (264 ginocchia) con caratteristiche basali simili; follow-up medio 10,1 ± 3,3 anni.",results:"OKS 40,6 ± 8,0 contro 38,8 ± 5,7 (non significativo); sopravvivenza senza revisione a 10 anni 92,3% contro 90,2% (p=0,618). Nel gruppo ≥10°: JLCA postoperatorio correlato con OKS (R = 0,43; p<0,001); JLCA fuori da 0°-5° di varo: OKS 35,6 ± 11,0 contro 42,4 ± 6,2 (p=0,022), PASS 33% contro 70% (p=0,011); inserto ≥7 mm: OKS 32,1 ± 12,1 contro 41,2 ± 5,9 (p=0,004), PASS 30% contro 81% (p=0,046). Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: esiti e sopravvivenza della UKA con varo ≥10° comparabili a quelli del varo <10° se il JLCA postoperatorio è 0°-5° e si evita l'inserto troppo spesso; un inserto che richiede upsizing impone di rivalutare lassità o sovraccarico del compartimento.",limits:"Retrospettivo, un solo centro; soglie di JLCA e di inserto ricavate dagli stessi dati (analisi ROC, rischio di sovradattamento) e sottogruppi piccoli · numero di revisioni assoluto non riportato · «nessuna differenza» fra gruppi senza intervalli non prova equivalenza.",perte:"Protesi monocompartimentale: fuori dalla tua attività di legamenti e preservazione, nel perimetro per il ginocchio. Non muove nessuna tensione."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Front Surg",h:"UKA mediale e menisco laterale lesionato: nessun peggioramento, otto coorti",v:"Meta-analisi di 8 coorti retrospettive (1709 pazienti): funzione SMD −0,06 (IC 95% da −0,26 a 0,14), mobilità MD 0,17° (da −1,58° a 1,92°), dolore laterale RR 1,10 (da 0,32 a 3,81). Lesioni asintomatiche non controindicano la UKA; radici, lesioni instabili e traumatiche escluse.",ax:"Zhou, Deng, Fu, Guo, Jiang, Huang, Gong",date:"set 2026",meta:"revisione sistematica con meta-analisi, 8 coorti retrospettive · [IV]",pmid:'42841039',doi:'10.3389/fsurg.2026.1913901',journal:"Frontiers in surgery",authors:"Zhou J, Deng H, Fu M, Guo J, Jiang Q, Huang C, Gong Z",design:"Revisione sistematica con meta-analisi (RevMan 5.4) fino al 1 marzo 2026 su otto banche dati, anche cinesi; GRADE per la certezza. Confronto fra pazienti con e senza lesione del menisco laterale prima di una UKA mediale per artrosi anteromediale. Livello IV (revisione di coorti retrospettive). Testo completo su PMC non aperto: numeri dall'abstract.",pop:"8 coorti retrospettive, 1709 pazienti in totale. Distribuzione delle lesioni, follow-up e tipo di impianto: non riportati nell'abstract.",results:"Funzione postoperatoria SMD −0,06 (IC 95% da −0,26 a 0,14; p=0,56); mobilità MD 0,17° (da −1,58° a 1,92°; p=0,85); dolore laterale RR 1,10 (da 0,32 a 3,81; p=0,89). Analisi di sensibilità stabili. Nessun aumento costante di revisione, fallimento dell'impianto o artrosi laterale, ma con pochi eventi.",concl:"Gli autori: anomalie degenerative lievi o asintomatiche del menisco laterale non compromettono gli esiti a breve-medio termine della UKA mediale e non sono da sole una controindicazione assoluta; non estrapolare a lesioni sintomatiche, instabili, traumatiche, alle radici o a perdita avanzata di cartilagine laterale.",limits:"Solo coorti retrospettive, con definizioni di «lesione» diverse e pochi eventi di revisione · l'intervallo del dolore laterale (0,32-3,81) è molto largo · esclude per autori le radici meniscali, che sono nella tua pratica.",perte:"Le lesioni radicali del menisco laterale, che tratti, sono espressamente escluse dalla conclusione: per te vale solo come cornice sul menisco laterale nella protesi. Non muove nessuna tensione."},{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"J Arthroplasty",h:"Bi-UKA o TKA nell'artrosi bicompartimentale: nessuna differenza a 24 mesi",v:"RCT esplorativo di Teheran su 56 pazienti analizzati (26 Bi-UKA, 30 TKA CR): Forgotten Joint Score a 24 mesi, differenza −4,91 punti (IC 95% da −17,92 a 8,09; p=0,453); nessuna complicanza maggiore, reintervento o revisione.",ax:"Sarzaeem, Ghanei, Omrani, Kouhsari, Kazemian, Dolikhani, Pourmojarab",date:"ott 2026",meta:"RCT esplorativo monocentrico, 56 pazienti analizzati · [II]",pmid:'42843679',doi:'10.1016/j.arth.2026.09.050',journal:"The Journal of arthroplasty",authors:"Sarzaeem MM, Ghanei A, Omrani FA, Kouhsari HJ, Kazemian G, Dolikhani M, Pourmojarab A",design:"RCT esplorativo 1:1 in un centro terziario (Teheran): Bi-UKA simultanea contro TKA con conservazione del crociato in artrosi femoro-tibiale bicompartimentale con LCA e LCP integri e rotula risparmiata; eleggibilità confermata in sala prima della randomizzazione. Esito primario Forgotten Joint Score a 24 mesi; analisi per protocollo su casi completi. Livello II per disegno. Testo completo non disponibile in PMC: numeri dall'abstract.",pop:"56 pazienti analizzati (26 Bi-UKA, 30 TKA); numero randomizzato e persi al follow-up: non riportati nell'abstract.",results:"Forgotten Joint Score a 24 mesi: differenza (Bi-UKA meno TKA) −4,91 punti (IC 95% da −17,92 a 8,09; p=0,453). Nessuna differenza di WOMAC, Knee Society Score, Oxford Knee Score e dolore VAS. Nessuna complicanza maggiore, reintervento o revisione in 24 mesi; analisi di sensibilità con modello misto coerente.",concl:"Gli autori: in pazienti selezionati la Bi-UKA non ha mostrato esiti riferiti dai pazienti migliori della TKA a 24 mesi; servono follow-up più lunghi per durata dell'impianto e sopravvivenza.",limits:"Esplorativo, 56 pazienti, un solo centro, analisi per protocollo su casi completi · l'intervallo (da −17,92 a 8,09) non esclude differenze di molti punti in entrambe le direzioni · 24 mesi non dicono nulla su usura e revisioni.",perte:"Protesi: fuori dalla tua pratica di legamenti e cartilagine, nel perimetro per il ginocchio. Il titolo dice «più vicina al nativo», ma l'abstract non mostra un vantaggio clinico. Non muove nessuna tensione."}];
var SUGGQ=[{"k": "kol", "n": "Simon Novak (Valdoltra Orthopaedic Hospital, Ankaran, Slovenia)", "w": "Slovenia, a poca distanza dal confine italiano: primo autore della nota tecnica di oggi sul MPFL a doppio fascio con retto femorale libero (PMID 42831219; afferenza letta nei metadati PubMed). Corrispondenza tecnica con il tuo MPFL e con il retto femorale come innesto. Sostituisce Michael Wagner (7 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Oggi, giovedì 8 ottobre, nove lavori e nessuna scheda rossa né arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida. Il lavoro del giorno è una nota tecnica sull'Arthroscopy Techniques del gruppo del Galeazzi di Milano, con D'Ambrosi: il prelievo mini-invasivo del tendine retto femorale, il tuo innesto di default. Incisione di circa tre centimetri a tre-quattro centimetri dal polo superiore della rotula, piano di dissezione riconosciuto da un sottile strato di grasso, stripper chiuso da almeno sette millimetri con il ginocchio fra dieci e venti gradi di flessione. Non ci sono pazienti né esiti, né intervalli di confidenza; la lunghezza dell'innesto riportata nel testo non è coerente con la dissezione descritta e non va usata. Tra le altre schede: una seconda nota tecnica, dalla Slovenia, ricostruisce il MPFL con retto femorale libero a doppio fascio, senza pazienti. Una coorte retrospettiva di sessantadue osteotomie ad apertura mediale mostra che lo slope sale di due-tre gradi con i tagli davanti al collaterale mediale e scende di meno di un grado con quello dietro, con deviazioni standard di tre-quattro gradi e senza esiti clinici nel riassunto. Una coorte del Mayo di duecentosedici protesi totali dopo osteotomia o protesi parziale non trova differenze di revisione a undici anni e mezzo, quattro contro sei per cento. Una coorte di novantatré adolescenti operati con hamstring non mostra deficit di forza a quattro mesi, mentre l'indice di simmetria cala per il guadagno dell'arto sano. Per le altre: una revisione sulla pillola anticoncezionale e il crociato senza associazione chiara, certezza molto bassa; tre lavori sulla protesi monocompartimentale e bicompartimentale. Tensioni: quella sul criterio di rientro riceve un dato di metodo, la simmetria può calare perché migliora l'arto sano. Nella seconda pagina trovi tredici brevi e tre proposte fuori dal solito, fra cui un modello di intelligenza artificiale che misura il notch sulle radiografie.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi, giovedì 8 ottobre: nove lavori, nessuna scheda rossa né arancione, nessun richiamo nuovo e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "E il lavoro del giorno?"}, {"chi": "A", "t": "Una nota tecnica del gruppo del Galeazzi di Milano, con D'Ambrosi, sul prelievo mini-invasivo del tendine retto femorale."}, {"chi": "B", "t": "Quindi il mio innesto di default. Come lo prelevano?"}, {"chi": "A", "t": "Incisione di circa tre centimetri, a tre-quattro centimetri dal polo superiore della rotula. Il piano si riconosce da un sottile strato di grasso, e usano uno stripper chiuso da almeno sette millimetri, con il ginocchio fra dieci e venti gradi."}, {"chi": "B", "t": "Con quali risultati?"}, {"chi": "A", "t": "Nessuno: non ci sono pazienti, né esiti, né intervalli di confidenza. E la lunghezza dell'innesto riportata nel testo non è coerente con la dissezione descritta, quindi non la usiamo."}, {"chi": "B", "t": "Quindi descrive una tecnica, non la valida."}, {"chi": "A", "t": "Esatto. Stesso discorso per una seconda nota, dalla Slovenia, sul legamento della rotula con retto femorale libero a doppio fascio."}, {"chi": "B", "t": "E sulle osteotomie?"}, {"chi": "A", "t": "Una coorte di sessantadue osteotomie ad apertura mediale: lo slope sale di due-tre gradi con i tagli davanti al collaterale mediale e scende di meno di un grado con quello dietro. Ma le deviazioni standard sono di tre-quattro gradi e gli esiti clinici non sono nel riassunto."}, {"chi": "B", "t": "Quindi un promemoria di pianificazione, non una prova."}, {"chi": "A", "t": "Sì. E una coorte del Mayo su duecentosedici protesi totali dopo osteotomia o protesi parziale non trova differenze di revisione a undici anni e mezzo."}, {"chi": "B", "t": "E sul criterio di rientro?"}, {"chi": "A", "t": "Novantatré adolescenti con hamstring: a quattro mesi la forza dell'arto operato non cala, ma l'indice di simmetria scende perché l'arto sano migliora. Una soglia di simmetria va letta con i valori assoluti."}];
